583	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
584	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
585	  const problems: string[] = [];
586	  const seen = new Set<string>();
587	  const dupes: string[] = [];
588	  for (const id of rawIds) {
589	    if (seen.has(id)) {
590	      if (!dupes.includes(id)) dupes.push(id);
591	    }
592	    seen.add(id);
593	  }
594	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
595	
596	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
597	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
598	
599	  if (problems.length > 0) throw new BizError(problems.join('\n'));
600	  return [...seen].sort();
601	}
