653	interface CoverageGap {
654	  id: string;
655	  r: ResourceRec;
656	  closures: ClosureRec[]; // 与该区间重叠的相关有效停用（按开始时间、标识排序）
657	}
658	
659	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
660	function findCoverageGaps(
661	  store: Store,
662	  ids: string[],
663	  startMin: number,
664	  endMin: number,
665	): CoverageGap[] {
666	  const gaps: CoverageGap[] = [];
667	  for (const id of ids) {
668	    const r = store.resources.find((x) => x.id === id)!;
669	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
670	    const closures = activeClosuresOf(store, id).filter((c) => {
671	      const cs = parseDateTime(c.start, '停用开始时间');
672	      const ce = parseDateTime(c.end, '停用结束时间');
673	      return cs < endMin && startMin < ce;
674	    });
675	    gaps.push({id, r, closures});
676	  }
677	  return gaps;
678	}
679	
680	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
681	function gapLines(gaps: CoverageGap[], indent: string): string[] {
682	  const lines: string[] = [];
683	  for (const g of gaps) {
684	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
685	    for (const c of g.closures) {
686	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
687	    }
688	  }
689	  return lines;
690	}
