770	interface ParsedFlags {
771	  values: Map<string, string[]>;
772	  positionals: string[];
773	}
774	
775	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
776	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
777	  const allowedSet = new Set(allowed);
778	  const multiSet = new Set(multi);
779	  const values = new Map<string, string[]>();
780	  const positionals: string[] = [];
781	
782	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
783	    if (inline !== undefined) return [inline, index];
784	    const v = args[index + 1];
785	    if (v === undefined || v.startsWith('-')) {
786	      throw new UsageError(`选项 --${key} 缺少值`);
787	    }
788	    return [v, index + 1];
789	  };
790	
791	  for (let i = 0; i < args.length; i++) {
792	    const a = args[i];
793	    if (a.startsWith('--')) {
794	      let key: string;
795	      let inline: string | undefined;
796	      const eq = a.indexOf('=');
797	      if (eq >= 0) {
798	        key = a.slice(2, eq);
799	        inline = a.slice(eq + 1);
800	      } else {
801	        key = a.slice(2);
802	      }
803	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
804	      let v: string;
805	      [v, i] = takeValue(key, inline, i);
806	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
807	      if (!multiSet.has(key) && values.has(key)) {
808	        throw new UsageError(`选项 --${key} 只能指定一次`);
809	      }
810	      const list = values.get(key) ?? [];
811	      list.push(v);
812	      values.set(key, list);
813	    } else if (a.startsWith('-') && a !== '-') {
814	      throw new UsageError(`未知参数: ${a}`);
815	    } else {
816	      positionals.push(a);
817	    }
818	  }
819	  return {values, positionals};
820	}
821	
822	function requireFlag(values: Map<string, string[]>, key: string): string {
823	  const v = values.get(key)?.[0];
824	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
825	  return v;
826	}
