832	async function cmdAddResource(args: string[]): Promise<void> {
833	  const {values, positionals} = parseFlags(args, ['type', 'name', 'open'], ['open']);
834	  if (positionals.length > 0) throw new UsageError(`add-resource 不接受位置参数: ${positionals.join(' ')}`);
835	
836	  const typeRaw = requireFlag(values, 'type');
837	  const type = RESOURCE_TYPE_MAP[typeRaw];
838	  if (!type) {
839	    throw new BizError(`资源类型非法: “${typeRaw}”，应为 venue（场地）、equipment（设备）或 person（人员）`);
840	  }
841	  const name = requireFlag(values, 'name');
842	  if (name.trim() === '') throw new BizError('资源名称不能为空');
843	
844	  const openRaw = values.get('open');
845	  if (!openRaw || openRaw.length === 0) throw new UsageError('至少需要一个 --open 开放区间');
846	  const open: Array<[string, string]> = openRaw.map((v) => {
847	    const iv = parseOpenInterval(v);
