884	async function cmdCreateBooking(args: string[]): Promise<void> {
885	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end'], ['resource']);
886	  if (positionals.length > 0) throw new UsageError(`create-booking 不接受位置参数: ${positionals.join(' ')}`);
887	
888	  const resourceArgs = values.get('resource');
889	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
890	  const startRaw = requireFlag(values, 'start');
891	  const endRaw = requireFlag(values, 'end');
892	
893	  const file = activeDataFile;
894	  const store = await loadStore(activeDataFile);
895	
896	  const ids = resolveResourceIds(store, resourceArgs);
897	  const startMin = parseDateTime(startRaw, '预约开始时间');
898	  const endMin = parseDateTime(endRaw, '预约结束时间');
899	  if (endMin <= startMin) {
900	    throw new BizError(`预约结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
901	  }
902	  assertOpenCoverage(store, ids, startMin, endMin);
903	  assertNoConflicts(findConflicts(store, ids, startMin, endMin), store);
904	
905	  // 校验全部通过，一次性占用全部资源并落盘
906	  store.bookingSeq += 1;
907	  const id = `B${String(store.bookingSeq).padStart(4, '0')}`;
908	  store.bookings.push({id, resourceIds: ids, start: startRaw, end: endRaw, status: 'active'});
909	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
910	  await saveStore(file, store);
911	  console.log(`已创建预约 ${id}`);
912	  console.log(`  时间: ${startRaw} → ${endRaw}`);
913	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
914	}
915	
916	async function cmdRescheduleBooking(args: string[]): Promise<void> {
917	  const {values, positionals} = parseFlags(args, ['start', 'end', 'resource'], ['resource']);
918	  if (positionals.length !== 1) {
919	    throw new UsageError('用法: reschedule-booking <预约标识> [--start ...] [--end ...] [--resource ...]');
920	  }
921	  const id = positionals[0];
922	
923	  const file = activeDataFile;
924	  const store = await loadStore(file);
925	  const booking = store.bookings.find((b) => b.id === id);
926	  if (!booking) throw new BizError(`未知预约标识: ${id}`);
927	  if (booking.status === 'cancelled') {
928	    throw new BizError(`预约 ${id} 已取消，不能改期`);
929	  }
930	
931	  const hasTime = values.has('start') || values.has('end');
932	  const hasResource = values.has('resource');
933	  if (!hasTime && !hasResource) {
934	    throw new BizError('未指定任何改动：请提供 --start/--end 修改时间，或 --resource 替换资源（可同时提供）');
935	  }
936	
937	  const startRaw = values.get('start')?.[0] ?? booking.start;
938	  const endRaw = values.get('end')?.[0] ?? booking.end;
939	  const startMin = parseDateTime(startRaw, '预约开始时间');
940	  const endMin = parseDateTime(endRaw, '预约结束时间');
941	  if (endMin <= startMin) {
942	    throw new BizError(`预约结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
943	  }
944	
945	  let ids: string[] = booking.resourceIds;
946	  if (hasResource) {
947	    const resourceArgs = values.get('resource')!;
948	    ids = resolveResourceIds(store, resourceArgs);
949	  }
950	
951	  assertOpenCoverage(store, ids, startMin, endMin);
952	  // 改期检查排除自身
953	  assertNoConflicts(findConflicts(store, ids, startMin, endMin, id), store);
954	
955	  // 全部可用后整体替换旧安排并落盘；失败则本进程内存与磁盘上的原安排都不变。
956	  // seriesId 不随改期变化：改期后仍属原系列。
957	  booking.start = startRaw;
958	  booking.end = endRaw;
959	  booking.resourceIds = ids;
960	  await saveStore(file, store);
961	  console.log(`已改期预约 ${id}（标识保持不变）`);
962	  if (booking.seriesId) console.log(`  所属系列: ${booking.seriesId}（改期后仍属该系列）`);
963	  console.log(`  时间: ${startRaw} → ${endRaw}`);
964	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
965	}
966	
967	// ---------------------------------------------------------------------------
968	// 批量原子改期（按本地清单一次交换多项预约的时段/资源）
969	// ---------------------------------------------------------------------------
970	
971	interface BatchTarget {
972	  index: number; // 清单中的 0 基序号
973	  booking: BookingRec;
974	  startRaw: string;
975	  endRaw: string;
976	  startMin: number;
977	  endMin: number;
978	  resourceIds: string[]; // 已校验、按标识排序，整体替换原集合
979	}
980	
981	interface BatchFailure {
982	  target: BatchTarget;
983	  gaps: CoverageGap[];
984	  external: Conflict[]; // 与本批之外有效预约的冲突
985	  internal: Array<{other: BatchTarget; shared: string[]}>; // 与本批其他目标安排的冲突
986	}
987	
988	// 读取清单文件：不可读、不是合法 JSON 均明确失败（绝不按空清单处理）
989	async function loadManifest(file: string): Promise<unknown> {
990	  let text: string;
991	  try {
992	    text = await readFile(file, 'utf8');
993	  } catch (err) {
994	    throw new BizError(`无法读取改期清单 ${file}: ${(err as Error).message}`);
995	  }
996	  try {
997	    return JSON.parse(text);
998	  } catch (err) {
999	    throw new BizError(`改期清单 ${file} 已损坏，不是合法 JSON：${(err as Error).message}`);
1000	  }
1001	}
1002	
1003	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
1004	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
1005	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
1006	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
1007	  }
1008	  const o = raw as Record<string, unknown>;
1009	  for (const k of Object.keys(o)) {
1010	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
1011	  }
1012	  if (!Array.isArray(o.items)) {
1013	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
1014	  }
1015	  const items = o.items as unknown[];
1016	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
1017	
1018	  const problems: string[] = [];
1019	  const records: Array<Record<string, unknown> | null> = [];
1020	  items.forEach((it, idx) => {
1021	    const at = `第 ${idx + 1} 项`;
1022	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
1023	      problems.push(`${at} 必须是对象`);
1024	      records.push(null);
1025	      return;
1026	    }
1027	    const rec = it as Record<string, unknown>;
1028	    for (const k of Object.keys(rec)) {
1029	      if (k !== 'bookingId' && k !== 'start' && k !== 'end' && k !== 'resourceIds') {
1030	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、start、end、resourceIds）`);
1031	      }
1032	    }
1033	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
1034	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
1035	    }
1036	    if (typeof rec.start !== 'string' || rec.start === '') {
1037	      problems.push(`${at} 的 start 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1038	    }
1039	    if (typeof rec.end !== 'string' || rec.end === '') {
1040	      problems.push(`${at} 的 end 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1041	    }
1042	    if (!Array.isArray(rec.resourceIds)) {
1043	      problems.push(`${at} 的 resourceIds 必须是非空数组（完整目标资源集合，整体替换原集合）`);
1044	    } else {
1045	      if (rec.resourceIds.length === 0) problems.push(`${at} 的 resourceIds 不能为空：资源集合整体替换，至少一个资源`);
1046	      rec.resourceIds.forEach((rid, j) => {
1047	        if (typeof rid !== 'string' || rid === '') {
1048	          problems.push(`${at}.resourceIds[${j}] 必须是非空资源标识字符串`);
1049	        }
1050	      });
1051	    }
1052	    records.push(rec);
1053	  });
1054	  if (problems.length > 0) {
1055	    throw new BizError(`改期清单 ${file} 内容非法，整批拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1056	  }
1057	  return records as Array<Record<string, unknown>>;
1058	}
1059	
1060	async function cmdRescheduleBatch(args: string[]): Promise<void> {
1061	  const {values, positionals} = parseFlags(args, []);
1062	  if (values.size > 0) {
1063	    throw new UsageError(
1064	      `reschedule-batch 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
1065	    );
1066	  }
1067	  if (positionals.length !== 1) {
1068	    throw new UsageError('用法: reschedule-batch <改期清单文件>');
1069	  }
1070	  const manifestFile = positionals[0];
1071	
1072	  const file = activeDataFile;
1073	  const store = await loadStore(file);
1074	  const records = parseManifestShape(await loadManifest(manifestFile), manifestFile);
1075	
1076	  // 第一阶段：逐项做与业务数据相关的基础校验，收集全部问题后一次性拒绝整批
1077	  const problems: string[] = [];
1078	  const seenBooking = new Map<string, number>(); // 标识 -> 首次出现的序号（1 基）
1079	  const planned: Array<BatchTarget | null> = [];
1080	  records.forEach((rec, idx) => {
1081	    const at = `第 ${idx + 1} 项（${rec.bookingId as string}）`;
1082	    let ok = true;
1083	
1084	    const firstAt = seenBooking.get(rec.bookingId as string);
1085	    if (firstAt !== undefined) {
1086	      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
1087	      ok = false;
1088	    } else {
1089	      seenBooking.set(rec.bookingId as string, idx + 1);
1090	    }
1091	
1092	    const booking = store.bookings.find((b) => b.id === rec.bookingId);
1093	    if (!booking) {
1094	      problems.push(`${at} 未知预约标识: ${rec.bookingId}`);
1095	      ok = false;
1096	    } else if (booking.status === 'cancelled') {
1097	      problems.push(`${at} 预约 ${booking.id} 已取消，不能改期`);
1098	      ok = false;
1099	    }
