1346	async function cmdCreateSeries(args: string[]): Promise<void> {
1347	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end', 'count'], ['resource']);
1348	  if (positionals.length > 0) throw new UsageError(`create-series 不接受位置参数: ${positionals.join(' ')}`);
1349	
1350	  const resourceArgs = values.get('resource');
1351	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
1352	  const startRaw = requireFlag(values, 'start');
1353	  const endRaw = requireFlag(values, 'end');
1354	  const count = parseOccurrences(requireFlag(values, 'count'));
1355	
1356	  const file = activeDataFile;
1357	  const store = await loadStore(file);
1358	
1359	  const ids = resolveResourceIds(store, resourceArgs);
1360	  const startMin = parseDateTime(startRaw, '首项开始时间');
1361	  const endMin = parseDateTime(endRaw, '首项结束时间');
1362	  if (endMin <= startMin) {
1363	    throw new BizError(`首项结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
1364	  }
1365	
1366	  // 先展开全部成员时间（含跨月、闰日、跨年、年份范围校验）
1367	  const members = planWeeklyMembers(startMin, endMin, count);
1368	
1369	  // 逐项校验：开放覆盖、与既有有效预约冲突、与系列内其他成员冲突
1370	  const failures: MemberFailure[] = [];
1371	  for (let i = 0; i < members.length; i++) {
1372	    const m = members[i];
1373	    const gaps = findCoverageGaps(store, ids, m.startMin, m.endMin);
1374	    const conflicts = findConflicts(store, ids, m.startMin, m.endMin);
1375	    const internal: Array<{other: PlannedMember; otherIndex: number}> = [];
1376	    for (let j = 0; j < members.length; j++) {
1377	      if (j === i) continue;
1378	      const o = members[j];
1379	      if (o.startMin < m.endMin && m.startMin < o.endMin) {
1380	        internal.push({other: o, otherIndex: j});
1381	      }
1382	    }
1383	    if (gaps.length > 0 || conflicts.length > 0 || internal.length > 0) {
1384	      failures.push({index: i, startRaw: m.startRaw, endRaw: m.endRaw, gaps, conflicts, internal});
1385	    }
1386	  }
1387	
1388	  if (failures.length > 0) {
1389	    // 按发生顺序报告所有失败项；任一项不满足则整批失败，不分配任何标识、不写文件
1390	    const blocks = failures.map((f) => {
1391	      const lines = [`第 ${f.index + 1} 项 ${f.startRaw} → ${f.endRaw}：`];
1392	      if (f.gaps.length > 0) {
1393	        lines.push('  开放不足资源:');
1394	        lines.push(...gapLines(f.gaps, '    '));
1395	      }
1396	      if (f.conflicts.length > 0) {
1397	        lines.push('  与以下既有预约冲突:');
1398	        for (const c of f.conflicts) {
1399	          lines.push(
1400	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
1401	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
1402	          );
1403	        }
1404	      }
1405	      if (f.internal.length > 0) {
1406	        lines.push('  与系列内其他成员冲突:');
1407	        for (const x of f.internal) {
1408	          lines.push(
1409	            `    - 第 ${x.otherIndex + 1} 项（${x.other.startRaw} → ${x.other.endRaw}）：双方时间重叠`,
1410	          );
1411	        }
1412	      }
1413	      return lines.join('\n');
1414	    });
1415	    throw new BizError(
1416	      `系列创建失败：共 ${failures.length} 项不满足条件（按发生顺序），整批未创建：\n${blocks.join('\n')}`,
1417	    );
1418	  }
1419	
1420	  // 全部验证通过：分配一个系列标识与每项预约标识，一次性落盘。
1421	  // 标识在此刻才生成，任何失败都不会推进计数。
1422	  store.seriesSeq += 1;
1423	  const seriesId = `S${String(store.seriesSeq).padStart(4, '0')}`;
1424	  const assigned: Array<{id: string; m: PlannedMember}> = [];
1425	  for (const m of members) {
1426	    store.bookingSeq += 1;
1427	    const id = `B${String(store.bookingSeq).padStart(4, '0')}`;
1428	    store.bookings.push({
1429	      id,
1430	      resourceIds: ids,
1431	      start: m.startRaw,
1432	      end: m.endRaw,
1433	      status: 'active',
1434	      seriesId,
1435	    });
1436	    assigned.push({id, m});
1437	  }
1438	  store.series.push({id: seriesId});
1439	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
1440	  store.series.sort((a, b) => a.id.localeCompare(b.id));
1441	  await saveStore(file, store);
1442	
1443	  console.log(`已创建按周重复系列 ${seriesId}（共 ${count} 项，每周一次，全部成员使用相同资源）`);
1444	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
1445	  assigned.forEach(({id, m}, i) => {
1446	    console.log(`  第 ${i + 1} 项 ${id}: ${m.startRaw} → ${m.endRaw}`);
1447	  });
1448	}
