1741	function renderBlocked(
1742	  store: Store,
1743	  w: WaitlistRec,
1744	  gaps: CoverageGap[],
1745	  conflicts: PendingConflict[],
1746	): string {
1747	  const lines = [`- 继续等待 ${w.id}：${w.start} → ${w.end}`];
1748	  if (gaps.length > 0) {
1749	    lines.push('    开放不足资源:');
1750	    lines.push(...gapLines(gaps, '      '));
1751	  }
1752	  if (conflicts.length > 0) {
1753	    lines.push('    冲突预约（共同资源时间重叠）:');
1754	    for (const c of conflicts) {
1755	      const note = c.fromWaitlistId ? `（本轮新预约，兑现自候补 ${c.fromWaitlistId}）` : '';
1756	      lines.push(
1757	        `      - ${c.bookingId}${note}（${c.start} → ${c.end}）：共同资源 ${formatResourceIds(store, c.shared)}`,
1758	      );
1759	    }
1760	  }
1761	  return lines.join('\n');
1762	}
