1774	async function cmdAddClosure(args: string[]): Promise<void> {
1775	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end']);
1776	  if (positionals.length > 0) throw new UsageError(`add-closure 不接受位置参数: ${positionals.join(' ')}`);
1777	
1778	  const resourceId = requireFlag(values, 'resource');
1779	  const startRaw = requireFlag(values, 'start');
1780	  const endRaw = requireFlag(values, 'end');
1781	
1782	  const file = activeDataFile;
1783	  const store = await loadStore(file);
1784	
1785	  const resource = store.resources.find((r) => r.id === resourceId);
1786	  if (!resource) throw new BizError(`未知资源标识: ${resourceId}`);
1787	
1788	  const startMin = parseDateTime(startRaw, '停用开始时间');
1789	  const endMin = parseDateTime(endRaw, '停用结束时间');
1790	  if (endMin <= startMin) {
1791	    throw new BizError(`停用结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
1792	  }
1793	
1794	  // 登记前检查该资源的全部有效预约（含系列成员与候补兑现预约；已取消不阻挡）。
1795	  // 区间左闭右开，端点相接不算重叠；有重叠即拒绝，不改期或取消任何预约。
1796	  const affected = store.bookings
1797	    .filter((b) => {
1798	      if (b.status !== 'active' || !b.resourceIds.includes(resourceId)) return false;
1799	      const bs = parseDateTime(b.start, '预约开始时间');
1800	      const be = parseDateTime(b.end, '预约结束时间');
1801	      return bs < endMin && startMin < be;
1802	    })
1803	    .sort((a, b) => a.id.localeCompare(b.id));
1804	  if (affected.length > 0) {
1805	    const lines = affected.map((b) => `- ${b.id}（${b.start} → ${b.end}）`);
1806	    throw new BizError(
1807	      `无法登记停用：资源 ${resourceId}（${resource.name}）在该区间存在有效预约` +
1808	        `（不自动改期或取消，请先处理）：\n${lines.join('\n')}`,
1809	    );
1810	  }
1811	
1812	  // 全部校验通过后才生成标识、改内存、落盘；相同内容再次登记也是另一记录
1813	  store.closureSeq += 1;
1814	  const id = `C${String(store.closureSeq).padStart(4, '0')}`;
1815	  store.closures.push({id, resourceId, start: startRaw, end: endRaw, status: 'active'});
1816	  store.closures.sort((a, b) => a.id.localeCompare(b.id));
1817	  await saveStore(file, store);
1818	  console.log(`已登记停用 ${id}`);
1819	  console.log(`  资源: ${resourceId}（${resource.name}）`);
1820	  console.log(`  时间: ${startRaw} → ${endRaw}`);
1821	  console.log('  该区间不再计入实际可用时间；取消停用请使用 cancel-closure。');
1822	}
