1850	async function cmdCancelClosure(args: string[]): Promise<void> {
1851	  const {values, positionals} = parseFlags(args, []);
1852	  if (values.size > 0) {
1853	    throw new UsageError(`cancel-closure 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`);
1854	  }
1855	  if (positionals.length !== 1) throw new UsageError('用法: cancel-closure <停用标识>');
1856	  const id = positionals[0];
1857	  if (!/^C\d{4,}$/.test(id)) throw new BizError(`停用标识非法: ${id}`);
1858	
1859	  const file = activeDataFile;
1860	  const store = await loadStore(file);
1861	  const closure = store.closures.find((c) => c.id === id);
1862	  if (!closure) throw new BizError(`未知停用标识: ${id}`);
1863	  if (closure.status === 'cancelled') {
1864	    // 幂等：重复取消成功且不做任何改动
1865	    console.log(`停用 ${id} 已是取消状态，未做改动。`);
1866	    return;
1867	  }
1868	  // 仅使该记录失效并保留历史；其他重叠停用仍有效，不自动创建预约或处理候补
1869	  closure.status = 'cancelled';
1870	  await saveStore(file, store);
1871	  console.log(`已取消停用 ${id}（记录保留），该区间恢复可用（不超出原开放时间）。`);
1872	}
