### Helpers

```ts
// 两组已排序互不重叠区间的交集
function intersectSegments(a: Array<[number, number]>, b: Array<[number, number]>): Array<[number, number]> {
  const out: Array<[number, number]> = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    const s = Math.max(a[i][0], b[j][0]);
    const e = Math.min(a[i][1], b[j][1]);
    if (s < e) out.push([s, e]);
    if (a[i][1] < b[j][1]) i++; else j++;
  }
  return out;
}

// 窗口内全部资源的共同实际可用时间（开放合并扣除有效停用后，跨资源求交，再截到窗口）
function commonAvailableSegments(store: Store, ids: string[], winStart: number, winEnd: number): Array<[number, number]> {
  let common: Array<[number, number]> = [[winStart, winEnd]];
  for (const id of ids) {
    const r = store.resources.find((x) => x.id === id)!;
    common = intersectSegments(common, availableSegmentsOf(store, r));
    if (common.length === 0) break;
  }
  return common;
}
```

Busy intervals from active bookings + selected items for the requested resource set:

```ts
// 与请求资源集合有共同资源的有效预约所占用的区间（用于从共同可用时间中扣除）
function busySegmentsOf(store, ids, extra: Array<{resourceIds: string[]; startMin: number; endMin: number}>): Array<[number,number]> {
  const wanted = new Set(ids);
  const busy: Array<[number, number]> = [];
  for (const b of store.bookings) {
    if (b.status !== 'active') continue;
    if (!b.resourceIds.some((id) => wanted.has(id))) continue;
    busy.push([parseDateTime(b.start,...), parseDateTime(b.end,...)]);
  }
  for (const e of extra) {
    if (!e.resourceIds.some((id) => wanted.has(id))) continue;
    busy.push([e.startMin, e.endMin]);
  }
  return mergeIntervals(busy);
}
```

