function renderBlockedFinal(store: Store, w: WaitlistRec, newBookingSource: Map<string,string>): string {
  if (w.kind === 'flexible') {
    const winStart = parseDateTime(w.start, '候补窗口开始时间');
    const winEnd = parseDateTime(w.end, '候补窗口结束时间');
    const duration = w.durationMin!;
    const common = commonAvailableSegments(store, w.resourceIds, winStart, winEnd);
    // 注意：此时 store.bookings 已包含本轮全部新预约（最终安排）
    const busy = busySegmentsOf(store, w.resourceIds, []);
    const free = subtractSegments(common, busy);
    const lines = [`- 继续等待 ${w.id}：弹性窗口 ${w.start} → ${w.end}，所需连续时长 ${duration} 分钟`];
    lines.push('    窗口内全部资源共同空闲区间（按最终安排，含本轮新预约占用）:');
    if (free.length === 0) {
      lines.push('      （空集：窗口内没有全部资源共同空闲的时间）');
    } else {
      for (const [s, e] of free) {
        lines.push(`      - ${fmt(s)} → ${fmt(e)}（${e - s} 分钟）`);
      }
    }
    return lines.join('\n');
  }
  // fixed
  const startMin = parseDateTime(w.start, '候补开始时间');
  const endMin = parseDateTime(w.end, '候补结束时间');
  const gaps = findCoverageGaps(store, w.resourceIds, startMin, endMin);
  const wanted = new Set(w.resourceIds);
  const conflicts: PendingConflict[] = [];
  for (const b of store.bookings) {
    if (b.status !== 'active') continue;
    const bStart = parseDateTime(b.start, '预约开始时间');
    const bEnd = parseDateTime(b.end, '预约结束时间');
    if (!(bStart < endMin && startMin < bEnd)) continue;
    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
    if (shared.length > 0) {
      conflicts.push({bookingId: b.id, start: b.start, end: b.end, shared, fromWaitlistId: newBookingSource.get(b.id)});
    }
  }
  conflicts.sort((a, b) => a.bookingId.localeCompare(b.bookingId));
  const lines = [`- 继续等待 ${w.id}：固定时段 ${w.start} → ${w.end}`];
  if (gaps.length > 0) {
    lines.push('    开放不足资源:');
    lines.push(...gapLines(gaps, '      '));
  }
  if (conflicts.length > 0) {
    lines.push('    冲突预约（共同资源时间重叠）:');
    for (const c of conflicts) {
      const note = c.fromWaitlistId ? `（本轮新预约，兑现自候补 ${c.fromWaitlistId}）` : '';
      lines.push(`      - ${c.bookingId}${note}（${c.start} → ${c.end}）：共同资源 ${formatResourceIds(store, c.shared)}`);
    }
  }
  return lines.join('\n');
}
